import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;
import org.jgrapht.isomorphism.IsomorphicGraphMapping;

import java.util.HashMap;
import java.util.Map;

public class GraphUtils {

    /**
     * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
     * @param graph the input graph
     * @param <V> the graph vertex type
     * @param <E> the graph edge type
     * @return a mapping from graph to graph
     */
    public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
        Map<V, V> mapping = new HashMap<>();
        for (V vertex : graph.vertexSet()) {
            mapping.put(vertex, vertex);
        }
        return new IsomorphicGraphMapping<>(graph, graph, mapping);
    }

    public static void main(String[] args) {
        // Example usage
        Graph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        graph.addVertex("A");
        graph.addVertex("B");
        graph.addEdge("A", "B");

        IsomorphicGraphMapping<String, DefaultEdge> identityMapping = identity(graph);
        System.out.println(identityMapping.getVertexCorrespondence("A", true)); // Output: A
        System.out.println(identityMapping.getVertexCorrespondence("B", true)); // Output: B
    }
}

