import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

static long compressTimeBucket(long timeBucket, int dayStep) {
    String timeBucketStr = String.valueOf(timeBucket);
    DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMdd");
    LocalDate date = LocalDate.parse(timeBucketStr, formatter);

    int dayOfMonth = date.getDayOfMonth();
    int adjustedDay = (dayOfMonth - 1) / dayStep * dayStep + 1;
    LocalDate adjustedDate = date.withDayOfMonth(adjustedDay);

    return Long.parseLong(adjustedDate.format(formatter));
}

import java.nio.charset.StandardCharsets;

public class UTF8Utils {
    /**
     * Computes the size of the utf8 string beginning at the specified {@code index} with the specified {@code length}.
     */
    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int size = 0;
        for (int i = index; i < index + len; i++) {
            char ch = str.charAt(i);
            if (ch <= 0x7F) {
                size += 1;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else if (Character.isHighSurrogate(ch)) {
                size += 4;
                i++; // Skip the low surrogate
            } else {
                size += 3;
            }
        }
        return size;
    }
}

