import java.util.Properties;

public class PropertySubstitutor {
    /**
     * Find the value corresponding to <code>key</code> in <code>props</code>. Then perform variable substitution on the found value.
     */
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        return substituteVariables(value, props);
    }

    private static String substituteVariables(String value, Properties props) {
        StringBuilder result = new StringBuilder();
        int start = 0;
        int end = 0;
        while ((start = value.indexOf("${", end)) != -1) {
            result.append(value, end, start);
            end = value.indexOf("}", start);
            if (end == -1) {
                break;
            }
            String varName = value.substring(start + 2, end);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            } else {
                result.append("${").append(varName).append("}");
            }
            end++;
        }
        result.append(value.substring(end));
        return result.toString();
    }
}

