import java.util.Stack;

public class Frame {
    private Stack<String> outputFrameStack;

    public Frame() {
        this.outputFrameStack = new Stack<>();
    }

    /**
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor.startsWith("(")) {
            // It's a method descriptor, extract argument types
            int endIndex = descriptor.indexOf(')');
            String arguments = descriptor.substring(1, endIndex);
            popTypes(arguments);
        } else {
            // It's a type descriptor
            popTypes(descriptor);
        }
    }

    private void popTypes(String types) {
        for (char type : types.toCharArray()) {
            switch (type) {
                case 'B': // byte
                case 'C': // char
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                case 'F': // float
                case 'J': // long
                case 'D': // double
                    outputFrameStack.pop();
                    break;
                case 'L': // object
                    // Find the end of the object descriptor
                    int endIndex = types.indexOf(';', types.indexOf(type));
                    outputFrameStack.pop();
                    break;
                case '[': // array
                    // Skip the array dimensions and pop the base type
                    int baseTypeIndex = types.indexOf(';', types.indexOf(type));
                    if (baseTypeIndex == -1) {
                        baseTypeIndex = types.length();
                    }
                    popTypes(types.substring(typeIndex, baseTypeIndex));
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor: " + type);
            }
        }
    }
}

import java.io.IOException;
import java.io.OutputStream;

public class CustomByteArrayOutputStream extends OutputStream {
    private byte[] buffer;
    private int count;

    public CustomByteArrayOutputStream(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("Negative initial size: " + size);
        }
        buffer = new byte[size];
    }

    @Override
    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException();
        } else if ((off < 0) || (off > b.length) || (len < 0) ||
                   ((off + len) > b.length) || ((off + len) < 0)) {
            throw new IndexOutOfBoundsException();
        } else if (len == 0) {
            return;
        }

        int newcount = count + len;
        if (newcount > buffer.length) {
            byte newbuf[] = new byte[Math.max(buffer.length << 1, newcount)];
            System.arraycopy(buffer, 0, newbuf, 0, count);
            buffer = newbuf;
        }
        System.arraycopy(b, off, buffer, count, len);
        count = newcount;
    }

    public int size() {
        return count;
    }

    public byte[] toByteArray() {
        return Arrays.copyOf(buffer, count);
    }

    public void writeTo(OutputStream out) throws IOException {
        out.write(buffer, 0, count);
    }

    public void reset() {
        count = 0;
    }

    public void ensureCapacity(int minCapacity) {
        if (minCapacity - buffer.length > 0)
            grow(minCapacity);
    }

    private void grow(int minCapacity) {
        int newCapacity = buffer.length << 1;
        if (newCapacity - minCapacity < 0)
            newCapacity = minCapacity;
        if (newCapacity < 0) {
            if (minCapacity < 0) // overflow
                throw new OutOfMemoryError();
            newCapacity = Integer.MAX_VALUE;
        }
        buffer = Arrays.copyOf(buffer, newCapacity);
    }
}

