public class LoggerHelper implements AppenderAttachable {
    private List<Appender> appenders = new ArrayList<>();

    @Override
    public boolean isAttached(Appender appender) {
        if (appender == null) {
            return false;
        }
        for (Appender attachedAppender : appenders) {
            if (appender.equals(attachedAppender)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public void addAppender(Appender newAppender) {
        if (newAppender != null) {
            appenders.add(newAppender);
        }
    }

    @Override
    public void removeAppender(Appender appender) {
        if (appender != null) {
            appenders.remove(appender);
        }
    }

    @Override
    public void removeAppender(String name) {
        if (name != null) {
            for (Appender appender : appenders) {
                if (name.equals(appender.getName())) {
                    appenders.remove(appender);
                    break;
                }
            }
        }
    }

    @Override
    public Enumeration<Appender> getAllAppenders() {
        return Collections.enumeration(appenders);
    }

    @Override
    public Appender getAppender(String name) {
        if (name != null) {
            for (Appender appender : appenders) {
                if (name.equals(appender.getName())) {
                    return appender;
                }
            }
        }
        return null;
    }
