            position += length;
        }

        return result;
    }
}

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class StringUtils {
    /**
     * <p>Unescapes any Java literals found in the <code>String</code>. For example, it will turn a sequence of <code>'\'</code> and <code>'n'</code> into a newline character, unless the <code>'\'</code> is preceded by another <code>'\'</code>.</p>
     * @param str the <code>String</code> to unescape, may be null
     * @return a new unescaped <code>String</code>, <code>null</code> if null string input
     */
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        Pattern p = Pattern.compile("\\\\(\\p{XDigit}{1,4}|.)");
        Matcher m = p.matcher(str);
        int lastMatchEnd = 0;
        while (m.find()) {
            sb.append(str, lastMatchEnd, m.start());
            String match = m.group(1);
            if (match.length() == 1) {
                char c = match.charAt(0);
                switch (c) {
                    case 'b':
                        sb.append('\b');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    default:
                        throw new Exception("Unrecognized escape sequence: \\" + c);
                }
            } else {
                sb.append((char) Integer.parseInt(match, 16));
            }
            lastMatchEnd = m.end();
        }
        sb.append(str.substring(lastMatchEnd));
        return sb.toString();
    }
}

