import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.alg.shortestpath.DijkstraShortestPath;
import org.jgrapht.graph.DefaultWeightedEdge;
import org.jgrapht.graph.SimpleWeightedGraph;

import java.util.Set;

public class GraphUtils {

    protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour.isEmpty()) {
            return null;
        }

        // Create a new graph to store the tour
        Graph<V, E> tourGraph = new SimpleWeightedGraph<>(DefaultWeightedEdge.class);

        // Add all vertices from the original graph to the tour graph
        tourGraph.addVertices(graph.vertexSet());

        // Add all edges from the tour set to the tour graph
        for (E edge : tour) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            tourGraph.addEdge(source, target, edge);
        }

        // Find a path that includes all edges in the tour
        DijkstraShortestPath<V, E> dijkstra = new DijkstraShortestPath<>(tourGraph);
        V startVertex = tourGraph.vertexSet().iterator().next();
        GraphPath<V, E> path = dijkstra.getPath(startVertex, startVertex);

        return path;
    }
}

