public class StringUnescaper {

    /**
     * Unescape a string DOT identifier.
     * @param input the input
     * @return the unescaped output
     */
    private String unescapeId(String input) {
        if (input == null) {
            return null;
        }

        // Replace escaped double quotes with a single double quote
        String unescaped = input.replace("\\\"", "\"");

        // Replace escaped backslashes with a single backslash
        unescaped = unescaped.replace("\\\\", "\\");

        return unescaped;
    }

    public static void main(String[] args) {
        StringUnescaper unescaper = new StringUnescaper();
        String escaped = "This is a \"test\" with a \\backslash\\";
        String unescaped = unescaper.unescapeId(escaped);
        System.out.println("Escaped: " + escaped);
        System.out.println("Unescaped: " + unescaped);
    }
}

