import java.util.ArrayList;
import java.util.List;
import javafx.util.Pair;

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    int currentSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSum += bounds.get(i);
        suffixSum.add(currentSum);
        totalSum += bounds.get(i);
    }

    java.util.Collections.reverse(suffixSum);
    return new Pair<>(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode<E> current = list.getHead();
    while (current != null) {
        ListNode<E> next = current.getNext();
        list.removeListNode((ListNodeImpl<E>) current);
        addListNode((ListNodeImpl<E>) current);
        current = next;
    }
}

