import javax.swing.*;
import java.awt.*;

public class TableUtils {
    /**
     * Selects the specified row in the specified JTable and scrolls the specified JScrollpane to the newly selected row.
     * More importantly, the call to repaint() is delayed long enough to have the table properly paint the newly selected row which may be offscreen.
     * @param row the row to select
     * @param table the JTable to select the row in
     * @param pane the JScrollPane containing the JTable
     */
    public static void selectRow(int row, JTable table, JScrollPane pane) {
        if (row >= 0 && row < table.getRowCount()) {
            table.setRowSelectionInterval(row, row);
            SwingUtilities.invokeLater(() -> {
                Rectangle rect = table.getCellRect(row, 0, true);
                pane.getViewport().scrollRectToVisible(rect);
                table.repaint();
            });
        }
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector putInt(final int intValue) {
        ensureCapacity(size + 4);
        data[size++] = (byte) (intValue >>> 24);
        data[size++] = (byte) (intValue >>> 16);
        data[size++] = (byte) (intValue >>> 8);
        data[size++] = (byte) intValue;
        return this;
    }

    private void ensureCapacity(int minCapacity) {
        if (minCapacity > data.length) {
            int newCapacity = Math.max(data.length << 1, minCapacity);
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    public byte[] toArray() {
        return Arrays.copyOf(data, size);
    }
}

